 1	pub fn parse_port(candidate: &str) -> i32 {
 2	    let trimmed = candidate.trim_start_matches(char::is_whitespace);
 3	    let (sign, digits_start) = match trimmed.as_bytes().first() {
 4	        Some(b'+') => (1_i32, 1_usize),
 5	        Some(b'-') => (-1_i32, 1_usize),
 6	        _ => (1_i32, 0_usize),
 7	    };
 8	
 9	    let digit_count = trimmed[digits_start..]
10	        .bytes()
11	        .take_while(|byte| byte.is_ascii_digit())
12	        .count();
13	
14	    if digit_count == 0 {
15	        return -1;
16	    }
17	
18	    let mut value: u32 = 0;
19	    for byte in trimmed[digits_start..digits_start + digit_count].bytes() {
20	        value = value.saturating_mul(10).saturating_add(u32::from(byte - b'0'));
21	        if value > 65_535 {
22	            return -1;
23	        }
24	    }
25	
26	    if sign < 0 {
27	        if value == 0 {
28	            return 0;
29	        }
30	        return -1;
31	    }
32	
33	    value as i32
34	}

