  3	pub struct URL {
  4	    scheme: String,
  5	    host: String,
  6	    port: i32,
  7	    path: String,
  8	    query: String,
  9	}
 10	
 11	impl URL {
 12	    pub fn new(input: &str) -> Self {
 13	        let without_fragment = input.split_once('#').map_or(input, |(head, _)| head);
 14	        let (base, query) = match without_fragment.split_once('?') {
 15	            Some((head, tail)) => (head, tail.to_string()),
 16	            None => (without_fragment, String::new()),
 17	        };
 18	
 19	        if let Some(scheme_end) = base.find("://") {
 20	            let scheme = base[..scheme_end].to_string();
 21	            let after_scheme = &base[scheme_end + 3..];
 22	            let (authority, path) = match after_scheme.find('/') {
 23	                Some(path_start) => (&after_scheme[..path_start], after_scheme[path_start..].to_string()),
 24	                None => (after_scheme, String::new()),
 25	            };
 26	
 27	            let host_and_port = authority
 28	                .split_once('@')
 29	                .map_or(authority, |(_, tail)| tail);
 30	
 31	            let (host, port) = match host_and_port.find(':') {
 32	                Some(colon) => (
 33	                    host_and_port[..colon].to_string(),
 34	                    parse_port(&host_and_port[colon + 1..]),
 35	                ),
 36	                None => (host_and_port.to_string(), -1),
 37	            };
 38	
 39	            Self {
 40	                scheme,
 41	                host,
 42	                port,
 43	                path,
 44	                query,
 45	            }
 46	        } else {
 47	            Self {
 48	                scheme: String::new(),
 49	                host: String::new(),
 50	                port: -1,
 51	                path: base.to_string(),
 52	                query,
 53	            }
 54	        }
 55	    }
 56	
 57	    pub fn scheme(&self) -> &str {
 58	        &self.scheme
 59	    }
 60	
 61	    pub fn host(&self) -> &str {
 62	        &self.host
 63	    }
 64	
